package com.mamtrex.hospital.clinical;
import com.mamtrex.hospital.shared.BaseEntity; import jakarta.persistence.*;
@Entity @Table(name="clinical_encounters") public class ClinicalEncounter extends BaseEntity { private String patientId; private String professionalId; private String startedAt; private String diagnosis; private String clinicalNote; protected ClinicalEncounter(){} public ClinicalEncounter(String patientId, String professionalId, String startedAt, String diagnosis, String clinicalNote){this.patientId=patientId; this.professionalId=professionalId; this.startedAt=startedAt; this.diagnosis=diagnosis; this.clinicalNote=clinicalNote;} public String getPatientId(){return patientId;} public String getProfessionalId(){return professionalId;} public String getStartedAt(){return startedAt;} public String getDiagnosis(){return diagnosis;} public String getClinicalNote(){return clinicalNote;} }
